using Npgsql;
using SCOPX.Api.Authentication;
using SCOPX.Infrastructure.Hospitals;
using SCOPX.Infrastructure.Procedures;
using SCOPX.Infrastructure.Sessions;
using SCOPX.Infrastructure.Users;
namespace SCOPX.Api.Procedures;
public static class ProcedureEndpoints
{
 public static IEndpointRouteBuilder MapProcedureEndpoints(this IEndpointRouteBuilder endpoints){
  var g=endpoints.MapGroup("/api/v1/procedures").RequireRateLimiting("api");
  g.MapGet("/patient/{patientId:guid}",async(Guid patientId,HttpContext c,IUserRepository u,ISessionRepository s,IHospitalMembershipRepository m,IProcedureRepository p,CancellationToken ct)=>{var a=await Resolve(c,u,s,m,ct);if(a is null)return Results.Unauthorized();if(!CanRead(a.Roles))return Results.Forbid();return Results.Ok(await p.ListForPatientAsync(a.HospitalId,a.UserId,patientId,ct));});
  g.MapGet("/{id:guid}",async(Guid id,HttpContext c,IUserRepository u,ISessionRepository s,IHospitalMembershipRepository m,IProcedureRepository p,CancellationToken ct)=>{var a=await Resolve(c,u,s,m,ct);if(a is null)return Results.Unauthorized();if(!CanRead(a.Roles))return Results.Forbid();var x=await p.GetAsync(a.HospitalId,a.UserId,id,ct);return x is null?Results.NotFound():Results.Ok(x);});
  g.MapPost("",async(ProcedureCreateRequest input,HttpContext c,IUserRepository u,ISessionRepository s,IHospitalMembershipRepository m,IProcedureRepository p,CancellationToken ct)=>{var a=await Resolve(c,u,s,m,ct);if(a is null)return Results.Unauthorized();if(!CanCreate(a.Roles))return Results.Forbid();var e=ValidateCreate(input);if(e is not null)return Results.BadRequest(new{error=e});try{var x=await p.CreateAsync(a.HospitalId,a.UserId,input,ct);return Results.Created($"/api/v1/procedures/{x!.Id}",x);}catch(PostgresException ex) when(ex.SqlState==PostgresErrorCodes.ForeignKeyViolation){return Results.NotFound(new{error="patient_not_found"});}});
  g.MapPost("/{id:guid}/start",async(Guid id,ProcedureStartRequest? input,HttpContext c,IUserRepository u,ISessionRepository s,IHospitalMembershipRepository m,IProcedureRepository p,CancellationToken ct)=>{var a=await Resolve(c,u,s,m,ct);if(a is null)return Results.Unauthorized();if(!a.Roles.Any(r=>new[]{"hospital_admin","doctor","endoscopy_technician"}.Contains(r,StringComparer.OrdinalIgnoreCase)))return Results.Forbid();var at=input?.StartedAt??DateTimeOffset.UtcNow;if(at>DateTimeOffset.UtcNow.AddMinutes(5))return Results.BadRequest(new{error="invalid_start_time"});return await p.StartAsync(a.HospitalId,a.UserId,id,at,ct)?Results.Ok(new{status="in_progress"}):Results.Conflict(new{error="invalid_procedure_transition"});});
  g.MapPost("/{id:guid}/complete",async(Guid id,ProcedureCompleteRequest input,HttpContext c,IUserRepository u,ISessionRepository s,IHospitalMembershipRepository m,IProcedureRepository p,CancellationToken ct)=>{var a=await Resolve(c,u,s,m,ct);if(a is null)return Results.Unauthorized();if(!a.Roles.Any(r=>new[]{"hospital_admin","doctor"}.Contains(r,StringComparer.OrdinalIgnoreCase)))return Results.Forbid();if(input.EndedAt>DateTimeOffset.UtcNow.AddMinutes(5)||input.Findings?.Length>8000||input.Impression?.Length>4000)return Results.BadRequest(new{error="invalid_procedure_completion"});return await p.CompleteAsync(a.HospitalId,a.UserId,a.MembershipId,id,input.EndedAt??DateTimeOffset.UtcNow,input.Findings,input.Impression,ct)?Results.Ok(new{status="completed"}):Results.Conflict(new{error="invalid_procedure_transition"});});
  return endpoints;
 }
 private static async Task<AuthContext?> Resolve(HttpContext c,IUserRepository u,ISessionRepository s,IHospitalMembershipRepository m,CancellationToken ct){var token=AuthHeaderReader.ReadBearer(c.Request.Headers.Authorization.ToString());if(token is null)return null;var sess=await s.FindActiveByTokenHashAsync(SessionToken.Hash(token),DateTimeOffset.UtcNow,ct);if(sess is null)return null;var user=await u.FindByIdAsync(sess.UserId,ct);if(user is not{Status:"active"})return null;if(!Guid.TryParse(c.Request.Headers["X-Hospital-ID"].ToString(),out var hid))return null;var member=await m.FindActiveForUserAndHospitalAsync(user.Id,hid,ct);return member is null?null:new(user.Id,member.MembershipId,hid,member.RoleCodes.ToArray());}
 private static bool CanRead(string[] r)=>r.Any(x=>new[]{"hospital_admin","doctor","nurse","auditor","endoscopy_technician"}.Contains(x,StringComparer.OrdinalIgnoreCase));
 private static bool CanCreate(string[] r)=>r.Any(x=>new[]{"hospital_admin","doctor","endoscopy_technician"}.Contains(x,StringComparer.OrdinalIgnoreCase));
 private static string? ValidateCreate(ProcedureCreateRequest x){if(x.PatientId==Guid.Empty)return"patient_required";if(string.IsNullOrWhiteSpace(x.ProcedureType)||x.ProcedureType.Length>64)return"invalid_procedure_type";if(x.RoomLabel?.Length>80||x.ClinicalIndication?.Length>4000)return"field_too_long";if(x.ScheduledAt>DateTimeOffset.UtcNow.AddYears(2))return"invalid_scheduled_at";return null;}
 private sealed record AuthContext(Guid UserId,Guid MembershipId,Guid HospitalId,string[] Roles);
}
